children.source:
isLink ? (
          <a
            class="md-navigation-rail-tab__anchor"
            href={href}
            target={this.target || undefined}
            rel={this.target ? SAFE_LINK_REL : undefined}
            tabIndex={-1}
            aria-hidden="true"
            part="anchor"
          >
            {this.renderInner()}
          </a>
        ) : (
          this.renderInner()
        )

declarations.value:
color-mix(
    in srgb,
    var(--md-sys-color-on-surface, #1C1B1F) calc(var(--_disabled-opacity) * 100%),
    transparent
  )
